"""Central timezone, including a TZif fallback for Android without tzdata."""
import base64
import io
import zlib
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

try:
    CENTRAL = ZoneInfo('America/Chicago')
except ZoneInfoNotFoundError:
    # IANA America/Chicago TZif data; includes future DST transition rules.
    CENTRAL = ZoneInfo.from_file(io.BytesIO(zlib.decompress(base64.b64decode(
        ''
    ))), key='America/Chicago')
